def _load_signature():
    entries = {}
    for line in SIGNATURE_DATA.strip().splitlines():
        fields = line.split('|')
        if len(fields) != 5 or fields[0] in entries:
            raise ValueError('invalid signature notes')
        name, *notes = fields
        if any(len(item) < 90 for item in notes):
            raise ValueError('underspecified signature note')
        entries[name] = tuple(notes)
    if len(entries) != 12:
        raise ValueError('incomplete signature notes')
    return MappingProxyType(entries)

SIGNATURE_FIELD_GUIDES = _load_signature()
